mkuse!{use std :: fmt :: Debug ;}
mkuse!{use std :: marker :: PhantomData ;}
mkuse!{use std :: sync :: atomic :: { AtomicPtr , AtomicU32 , AtomicUsize , Ordering } ;}
mkuse!{use rustc_index :: Idx ;}
mkitem!{mkstruct!{struct Slot < V > { value : V , index_and_lock : AtomicU32 , }}}
mkitem!{mkstruct!{# [doc = " This uniquely identifies a single `Slot<V>` entry in the buckets map, and provides accessors for"] # [doc = " either getting the value or putting a value."] # [derive (Copy , Clone , Debug)] struct SlotIndex { bucket_idx : usize , entries : usize , index_in_bucket : usize , }}}
mkitem!{const ENTRIES_BY_BUCKET : [usize ; 21] = { let mut entries = [0 ; 21] ; let mut key = 0 ; loop { let si = SlotIndex :: from_index (key) ; entries [si . bucket_idx] = si . entries ; if key == 0 { key = 1 ; } else if key == (1 << 31) { break ; } else { key <<= 1 ; } } entries } ;}
mkitem!{mkimpl!{impl SlotIndex { # [inline] const fn from_index (idx : u32) -> Self { const FIRST_BUCKET_SHIFT : usize = 12 ; if idx < (1 << FIRST_BUCKET_SHIFT) { return SlotIndex { bucket_idx : 0 , entries : 1 << FIRST_BUCKET_SHIFT , index_in_bucket : idx as usize , } ; } let bucket = idx . ilog2 () as usize ; let entries = 1 << bucket ; SlotIndex { bucket_idx : bucket - FIRST_BUCKET_SHIFT + 1 , entries , index_in_bucket : idx as usize - entries , } } # [inline] unsafe fn get < V : Copy > (& self , buckets : & [AtomicPtr < Slot < V > > ; 21]) -> Option < (V , u32) > { let bucket = unsafe { buckets . get_unchecked (self . bucket_idx) } ; let ptr = bucket . load (Ordering :: Acquire) ; if ptr . is_null () { return None ; } assert ! (self . index_in_bucket < self . entries) ; let slot = unsafe { ptr . add (self . index_in_bucket) } ; let index_and_lock = unsafe { & (* slot) . index_and_lock } ; let current = index_and_lock . load (Ordering :: Acquire) ; let index = match current { 0 => return None , 1 => return None , _ => current - 2 , } ; let value = unsafe { (* slot) . value } ; Some ((value , index)) } fn bucket_ptr < V > (& self , bucket : & AtomicPtr < Slot < V > >) -> * mut Slot < V > { let ptr = bucket . load (Ordering :: Acquire) ; if ptr . is_null () { self . initialize_bucket (bucket) } else { ptr } } # [cold] fn initialize_bucket < V > (& self , bucket : & AtomicPtr < Slot < V > >) -> * mut Slot < V > { static LOCK : std :: sync :: Mutex < () > = std :: sync :: Mutex :: new (()) ; let _allocator_guard = LOCK . lock () . unwrap_or_else (| e | e . into_inner ()) ; let ptr = bucket . load (Ordering :: Acquire) ; if ptr . is_null () { let bucket_layout = std :: alloc :: Layout :: array :: < Slot < V > > (self . entries as usize) . unwrap () ; assert ! (bucket_layout . size () > 0) ; let allocated = unsafe { std :: alloc :: alloc_zeroed (bucket_layout) . cast :: < Slot < V > > () } ; if allocated . is_null () { std :: alloc :: handle_alloc_error (bucket_layout) ; } bucket . store (allocated , Ordering :: Release) ; allocated } else { ptr } } # [doc = " Returns true if this successfully put into the map."] # [inline] fn put < V > (& self , buckets : & [AtomicPtr < Slot < V > > ; 21] , value : V , extra : u32) -> bool { let bucket = unsafe { buckets . get_unchecked (self . bucket_idx) } ; let ptr = self . bucket_ptr (bucket) ; assert ! (self . index_in_bucket < self . entries) ; let slot = unsafe { ptr . add (self . index_in_bucket) } ; let index_and_lock = unsafe { & (* slot) . index_and_lock } ; match index_and_lock . compare_exchange (0 , 1 , Ordering :: AcqRel , Ordering :: Acquire) { Ok (_) => { unsafe { (& raw mut (* slot) . value) . write (value) ; } index_and_lock . store (extra . checked_add (2) . unwrap () , Ordering :: Release) ; true } Err (1) => panic ! ("caller raced calls to put()") , Err (_) => false , } } }}}
mkitem!{mkstruct!{# [doc = " In-memory cache for queries whose keys are densely-numbered IDs"] # [doc = " (e.g `CrateNum`, `LocalDefId`), and can therefore be used as indices"] # [doc = " into a dense vector of cached values."] # [doc = ""] # [doc = " (As of [#124780] the underlying storage is not an actual `Vec`, but rather"] # [doc = " a series of increasingly-large buckets, for improved performance when the"] # [doc = " parallel frontend is using multiple threads.)"] # [doc = ""] # [doc = " Each entry in the cache stores the query's return value (`V`), and also"] # [doc = " an associated index (`I`), which in practice is a `DepNodeIndex` used for"] # [doc = " query dependency tracking."] # [doc = ""] # [doc = " [#124780]: https://github.com/rust-lang/rust/pull/124780"] pub struct VecCache < K : Idx , V , I > { buckets : [AtomicPtr < Slot < V > > ; 21] , present : [AtomicPtr < Slot < () > > ; 21] , len : AtomicUsize , key : PhantomData < (K , I) > , }}}
mkitem!{mkimpl!{impl < K : Idx , V , I > Default for VecCache < K , V , I > { fn default () -> Self { VecCache { buckets : Default :: default () , key : PhantomData , len : Default :: default () , present : Default :: default () , } } }}}
mkitem!{mkimpl!{unsafe impl < K : Idx , # [may_dangle] V , I > Drop for VecCache < K , V , I > { fn drop (& mut self) { assert ! (! std :: mem :: needs_drop ::< K > ()) ; assert ! (! std :: mem :: needs_drop ::< V > ()) ; for (idx , bucket) in self . buckets . iter () . enumerate () { let bucket = bucket . load (Ordering :: Acquire) ; if ! bucket . is_null () { let layout = std :: alloc :: Layout :: array :: < Slot < V > > (ENTRIES_BY_BUCKET [idx]) . unwrap () ; unsafe { std :: alloc :: dealloc (bucket . cast () , layout) ; } } } for (idx , bucket) in self . present . iter () . enumerate () { let bucket = bucket . load (Ordering :: Acquire) ; if ! bucket . is_null () { let layout = std :: alloc :: Layout :: array :: < Slot < () > > (ENTRIES_BY_BUCKET [idx]) . unwrap () ; unsafe { std :: alloc :: dealloc (bucket . cast () , layout) ; } } } } }}}
mkitem!{mkimpl!{impl < K , V , I > VecCache < K , V , I > where K : Eq + Idx + Copy + Debug , V : Copy , I : Idx + Copy , { # [inline (always)] pub fn lookup (& self , key : & K) -> Option < (V , I) > { let key = u32 :: try_from (key . index ()) . unwrap () ; let slot_idx = SlotIndex :: from_index (key) ; match unsafe { slot_idx . get (& self . buckets) } { Some ((value , idx)) => Some ((value , I :: new (idx as usize))) , None => None , } } # [inline] pub fn complete (& self , key : K , value : V , index : I) { let key = u32 :: try_from (key . index ()) . unwrap () ; let slot_idx = SlotIndex :: from_index (key) ; if slot_idx . put (& self . buckets , value , index . index () as u32) { let present_idx = self . len . fetch_add (1 , Ordering :: Relaxed) ; let slot = SlotIndex :: from_index (present_idx as u32) ; assert ! (slot . put (& self . present , () , key)) ; } } pub fn iter (& self , f : & mut dyn FnMut (& K , & V , I)) { for idx in 0 .. self . len . load (Ordering :: Acquire) { let key = SlotIndex :: from_index (idx as u32) ; match unsafe { key . get (& self . present) } { None => unreachable ! () , Some ((() , key)) => { let key = K :: new (key as usize) ; let value = self . lookup (& key) . unwrap () ; f (& key , & value . 0 , value . 1) ; } } } } }}}
